-- HSK 3급 · HSK 4급 서랍 추가
-- Supabase SQL Editor → New query 에 이 파일 전체를 붙여넣고 Run.
-- 3급: 新HSK 1~3급 단어 600 (1급→2급→3급 순서, 같은 한자는 합쳐서 594개)
-- 4급: 해커스 HSK 1-4급 필수 단어 1200 인덱스 (병음 가나다순, 같은 한자는 합쳐서 1192개)
--      인덱스 PDF에는 뜻이 없어서 1~3급은 1~3급 단어장의 뜻, 나머지는 해커스 실전 단어장과 보충 뜻을 넣었습니다.
insert into hsk_decks(id, name, color, sort) values ('hsk3','HSK 3급','#34c759',1), ('hsk4lv','HSK 4급','#5856d6',2)
on conflict (id) do update set name = excluded.name, sort = excluded.sort;
update hsk_decks set name = '해커스 실전 2회', sort = 3 where id = 'hsk4';
update hsk_decks set name = '해커스 실전 3회', sort = 4 where id = 'mock';
update hsk_decks set sort = 5 where id = 'hak45';
insert into hsk_words(deck_id, ord, han, py, mn)
select 'hsk3', (select coalesce(max(ord),0) from hsk_words where deck_id='hsk3') + o::int, e->>0, e->>1, e->>2
